/* 把 x 的第 k 位起的 n 位整体改写为 value（value 低位对齐） */
static unsigned put_field(unsigned x, int k, int n, unsigned value)
{
    unsigned m = ((1u << n) - 1u) << k;
    return (x & ~m) | ((value << k) & m);
}

