#include <stdio.h>

static void swap_xor(int *p, int *q)
{
    if (p != q) { *p ^= *q; *q ^= *p; *p ^= *q; }
}

static void swap_tmp(int *p, int *q)
{
    int t = *p; *p = *q; *q = t;
}

int main(void)
{
    int arr[3] = {1, 2, 3};

    swap_xor(&arr[0], &arr[2]);
    printf("%d %d %d\n", arr[0], arr[1], arr[2]);
    swap_xor(&arr[1], &arr[1]);       /* 自交换，有保护所以安全 */
    printf("%d %d %d\n", arr[0], arr[1], arr[2]);
    swap_tmp(&arr[0], &arr[1]);
    printf("%d %d %d\n", arr[0], arr[1], arr[2]);
    return 0;
}

