#include <stdio.h>

static unsigned getbits(unsigned x, int p, int n)
{
    return (x >> (p + 1 - n)) & ~(~0u << n);
}

int main(void)
{
    unsigned x = 0x12345678u;

    printf("%X\n", getbits(x, 3, 4));     /* 最低半字节 */
    printf("%X\n", getbits(x, 7, 4));     /* 第二个半字节 */
    printf("%X\n", getbits(x, 15, 8));    /* 第二个字节 */
    printf("%X\n", getbits(x, 31, 8));    /* 最高字节 */
    printf("%08X\n", ~(~0u << 12));       /* 低 12 位掩码 */
    return 0;
}

#include <stdio.h>

/* 用 unsigned short 模拟 16 位字长，掩码与移位都在 16 位内进行 */
static unsigned getbits16(unsigned short x, int p, int n)
{
    unsigned short m = (unsigned short)~((unsigned short)(~0u << n));
    return (unsigned)((unsigned short)(x >> (p + 1 - n)) & m);
}

int main(void)
{
    unsigned short x = 0xABCDu;   /* 1010 1011 1100 1101 */

    printf("%04X\n", (unsigned)x);
    printf("%X\n", getbits16(x, 15, 4));   /* 最高 4 位 */
    printf("%X\n", getbits16(x, 11, 4));
    printf("%X\n", getbits16(x, 3, 4));    /* 最低 4 位 */
    printf("%04X\n", (unsigned)(unsigned short)~((unsigned short)(~0u << 6)));
    return 0;
}

