#include <stdio.h>

#define S_MATH    0x01u
#define S_CHINESE 0x02u
#define S_ENGLISH 0x04u
#define S_PHYSICS 0x08u

static void show(const char *tag, unsigned set) {
    printf("%s:", tag);
    if (set & S_MATH)    printf(" 数学");
    if (set & S_CHINESE) printf(" 语文");
    if (set & S_ENGLISH) printf(" 英语");
    if (set & S_PHYSICS) printf(" 物理");
    if (set == 0)        printf(" (空集)");
    printf("   [%#x]\n", set);
}

int main(void) {
    unsigned chosen = S_MATH | S_ENGLISH;
    show("初选  ", chosen);
    chosen |= S_PHYSICS;          /* 加入一项，幂等 */
    chosen |= S_PHYSICS;          /* 再加一次，结果不变 */
    show("加物理", chosen);
    chosen &= ~S_MATH;            /* 删除一项 */
    show("去数学", chosen);
    if (chosen & (S_CHINESE | S_PHYSICS))
        printf("判断: 含语文或物理之一 -> 真\n");
    chosen &= ~(S_ENGLISH | S_PHYSICS);
    show("全清空", chosen);
    return 0;
}

#include <stdio.h>

#define OPT_UPPER   0x01u   /* 转大写     */
#define OPT_TRIM    0x02u   /* 去掉空格   */
#define OPT_REVERSE 0x04u   /* 反转顺序   */

static void process(const char *s, unsigned opt) {
    char buf[64];
    int i, n = 0;
    for (i = 0; s[i] != '\0' && n < 63; i++) {
        char c = s[i];
        if ((opt & OPT_TRIM) && c == ' ') continue;
        if ((opt & OPT_UPPER) && c >= 'a' && c <= 'z') c = (char)(c - 'a' + 'A');
        buf[n++] = c;
    }
    buf[n] = '\0';
    if (opt & OPT_REVERSE) {
        int lo = 0, hi = n - 1;
        while (lo < hi) { char t = buf[lo]; buf[lo] = buf[hi]; buf[hi] = t; lo++; hi--; }
    }
    printf("opt=%#04x -> \"%s\"\n", opt, buf);
}

int main(void) {
    process("hello world", 0);
    process("hello world", OPT_UPPER);
    process("hello world", OPT_UPPER | OPT_TRIM);
    process("hello world", OPT_UPPER | OPT_TRIM | OPT_REVERSE);
    return 0;
}

